arguments.command:
cat > /tmp/gh-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) printf '%s\n' "x-access-token" ;;
  *Password*) printf '%s\n' "$GITHUB_TOKEN" ;;
  *) printf '%s\n' "" ;;
esac
EOF
chmod +x /tmp/gh-askpass.sh && cd /tmp/phoebe-convo && GIT_ASKPASS=/tmp/gh-askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/phoebe 2>&1 | tail -5
